#!/usr/bin/env bash
set -euo pipefail

# Resyncs ./src/typebox/typebox.ts from the open-chat repo.
#
# Provenance: ts/library/src/typebox/typebox.ts is a *copy* of
# <open-chat>/frontend/openchat-agent/src/typebox.ts. It is not generated in
# this repo. Upstream it is generated by <open-chat>/scripts/generate-typebox-types.sh
# which exports the canister types via `cargo run -p ts_exporter`, runs
# `npm run typebox` (ts2typebox) and then applies two awk fixups.
#
# The SDK validates every request/response against these schemas at runtime, so
# if this copy falls behind the backend, newly added fields are silently rejected
# or dropped. Run this script whenever the OpenChat backend API changes.
#
# Usage:
#   ./sync-typebox.sh /path/to/open-chat
#   OPEN_CHAT_REPO=/path/to/open-chat ./sync-typebox.sh
#
#   # also re-run the upstream generator first (needs rust and the open-chat
#   # frontend npm deps installed in that repo):
#   ./sync-typebox.sh /path/to/open-chat --regenerate

SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)

REPO=${OPEN_CHAT_REPO:-}
REGENERATE=false

for arg in "$@"; do
    case "$arg" in
        --regenerate) REGENERATE=true ;;
        -h|--help)
            echo "usage: $0 <path-to-open-chat-repo> [--regenerate]"
            echo "   or: OPEN_CHAT_REPO=<path> $0 [--regenerate]"
            exit 0
            ;;
        *) REPO=$arg ;;
    esac
done

if [ -z "$REPO" ]; then
    echo "error: path to the open-chat repo is required." >&2
    echo "usage: $0 <path-to-open-chat-repo> [--regenerate]" >&2
    echo "   or: OPEN_CHAT_REPO=<path> $0 [--regenerate]" >&2
    exit 1
fi

UPSTREAM="$REPO/frontend/openchat-agent/src/typebox.ts"
GENERATOR="$REPO/scripts/generate-typebox-types.sh"
TARGET="$SCRIPT_DIR/src/typebox/typebox.ts"

if [ "$REGENERATE" = true ]; then
    if [ ! -f "$GENERATOR" ]; then
        echo "error: generator not found: $GENERATOR" >&2
        exit 1
    fi
    echo "Regenerating upstream typebox definitions..."
    bash "$GENERATOR"
fi

if [ ! -f "$UPSTREAM" ]; then
    echo "error: upstream file not found: $UPSTREAM" >&2
    echo "       is '$REPO' really the root of the open-chat repo?" >&2
    exit 1
fi

cp "$UPSTREAM" "$TARGET"
echo "Copied $UPSTREAM -> $TARGET"
echo "Next: run 'npm run build' and 'npx vitest run' in $SCRIPT_DIR, then review the diff."
